int turnAngle = 50;   // max turn per time (degrees)
int branchMin = 0;    // number of branches (min)
int branchMax = 0;    // number of branches (max)
float roughness = 0.5;// edge roughness (0 = smooth)
float endRatio = 0.7; // radius at the end (1 = no shrink)
for (int i = 0; i < 40; i++) { tunnel(srand(i * 2, 0, width), srand(i * 2 + 1, caveTop, height), airId, 1.5, 10); }

